catalog_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
   var case_sys_id = getParameterValue('case_sys_id');

	if (case_sys_id == ""){
		return; //Nothing else to process
	}

	g_form.setValue('case_sys_id', case_sys_id);

	//Make an ajax call to load the case info (JSON)
	var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMUtils');
	ga.addParam('sysparm_name', 'getWorkplaceInspectionDraft');
	ga.addParam('sysparm_case_sys_id', case_sys_id);
	ga.getXML(filloutCase);

}

function filloutCase(response) {

	var answer = JSON.parse(response.responseXML.documentElement.getAttribute("answer"));

	//Load case information
	g_form.setValue('other_inspectors',answer.other_inspectors);
	g_form.setValue('building',answer.building);
	g_form.setValue('floor_inspected',answer.floor_inspected);
	g_form.setValue('area_s_inspected',answer.area_s_inspected);
	g_form.setValue('date_time_of_inspection',answer.date_time_of_inspection);
	g_form.setValue('shared_space',answer.shared_space);

	//TODO: Check boxes
	if (answer.floors_are_clear == "true"){g_form.setValue('floors_are_clear', true);}
	if (answer.signs_are_posted_when_the_floors_are_wet == "true"){g_form.setValue('signs_are_posted_when_the_floors_are_wet', true);}
	if (answer.walkways_are_free_from_obstructions == "true"){g_form.setValue('walkways_are_free_from_obstructions', true);}
	if (answer.main_aisles_are_at_least_36_inches_wide == "true"){g_form.setValue('main_aisles_are_at_least_36_inches_wide', true);}
	if (answer.lighting_levels_are_operational_entrance_office_and_stairways == "true"){g_form.setValue('lighting_levels_are_operational_entrance_office_and_stairways', true);}
	if (answer.air_quality_is_adequate == "true"){g_form.setValue('air_quality_is_adequate', true);}
	if (answer.temperature_is_adequate == "true"){g_form.setValue('temperature_is_adequate', true);}
	if (answer.noise_levels_are_appropriate == "true"){g_form.setValue('noise_levels_are_appropriate', true);}
	if (answer.ventilation_is_adequate == "true"){g_form.setValue('ventilation_is_adequate', true);}
	if (answer.hazardous_products_are_properly_identified == "true"){g_form.setValue('hazardous_products_are_properly_identified', true);}
	if (answer.ceiling_tiles_are_in_good_condition == "true"){g_form.setValue('ceiling_tiles_are_in_good_condition', true);}
	if (answer.cords_and_plugs_are_in_good_condition == "true"){g_form.setValue('cords_and_plugs_are_in_good_condition', true);}
	if (answer.power_bars_are_not_plugged_into_another_power_bar_daisy_chain == "true"){g_form.setValue('power_bars_are_not_plugged_into_another_power_bar_daisy_chain', true);}
	if (answer.space_heaters_are_csa_approved_and_have_an_auto_shut_off_feature == "true"){g_form.setValue('space_heaters_are_csa_approved_and_have_an_auto_shut_off_feature', true);}
	if (answer.wire_management_in_good_condition_and_are_not_a_tripping_hazard == "true"){g_form.setValue('wire_management_in_good_condition_and_are_not_a_tripping_hazard', true);}
	if (answer.first_aid_kits_are_inspected_on_a_monthly_basis_and_are_they_accessible == "true"){g_form.setValue('first_aid_kits_are_inspected_on_a_monthly_basis_and_are_they_accessible', true);}
	if (answer.fire_extinguishers_are_hung_properly_are_accessible_inspected_on_a_monthly_basis == "true"){g_form.setValue('fire_extinguishers_are_hung_properly_are_accessible_inspected_on_a_monthly_basis', true);}
	if (answer.emergency_exits_are_free_from_obstruction == "true"){g_form.setValue('emergency_exits_are_free_from_obstruction', true);}
	if (answer.emergency_exits_signs_are_properly_lit == "true"){g_form.setValue('emergency_exits_signs_are_properly_lit', true);}
	if (answer.evacuation_plan_is_properly_posted == "true"){g_form.setValue('evacuation_plan_is_properly_posted', true);}
	if (answer.fire_hose_cabinets_are_accessible_and_free_of_obstruction == "true"){g_form.setValue('fire_hose_cabinets_are_accessible_and_free_of_obstruction', true);}
	if (answer.pull_stations_are_accessible_and_free_of_obstruction == "true"){g_form.setValue('pull_stations_are_accessible_and_free_of_obstruction', true);}
	if (answer.security_systems_intercom_duress_alarm_etc == "true"){g_form.setValue('security_systems_intercom_duress_alarm_etc', true);}
	if (answer.is_the_office_furniture_ergonomic_and_in_good_condition == "true"){g_form.setValue('is_the_office_furniture_ergonomic_and_in_good_condition', true);}
	if (answer.paper_trimmer_cutter_blade_is_closed_and_secured == "true"){g_form.setValue('paper_trimmer_cutter_blade_is_closed_and_secured', true);}
	if (answer.desk_and_file_cabinet_drawers_are_closed_while_not_in_use == "true"){g_form.setValue('desk_and_file_cabinet_drawers_are_closed_while_not_in_use', true);}
	if (answer.is_the_office_furniture_free_from_sharp_edges_and_corners == "true"){g_form.setValue('is_the_office_furniture_free_from_sharp_edges_and_corners', true);}
	if (answer.printer_toners_are_handled_as_a_hazardous_substance_and_are_stored_properly == "true"){g_form.setValue('printer_toners_are_handled_as_a_hazardous_substance_and_are_stored_properly', true);}
	if (answer.see_the_posting_requirements_document_in_the_health_and_safety_representative_toolbox == "true"){g_form.setValue('see_the_posting_requirements_document_in_the_health_and_safety_representative_toolbox', true);}
	if (answer.materials_are_stored_securely_and_at_an_appropriate_height == "true"){g_form.setValue('materials_are_stored_securely_and_at_an_appropriate_height', true);}
	if (answer.material_and_storage_systems_are_secured_from_tipping_and_are_in_good_condition == "true"){g_form.setValue('material_and_storage_systems_are_secured_from_tipping_and_are_in_good_condition', true);}
	if (answer.step_stools_and_ladders_are_available_and_in_good_condition == "true"){g_form.setValue('step_stools_and_ladders_are_available_and_in_good_condition', true);}
	if (answer.storage_room_is_maintained_and_clean_if_applicable == "true"){g_form.setValue('storage_room_is_maintained_and_clean_if_applicable', true);}
	if (answer.washrooms_are_clean == "true"){g_form.setValue('washrooms_are_clean', true);}
	if (answer.hygiene_supplies_are_available_soap_towels_bathroom_tissue == "true"){g_form.setValue('hygiene_supplies_are_available_soap_towels_bathroom_tissue', true);}
	if (answer.waste_containers_are_emptied_daily == "true"){g_form.setValue('waste_containers_are_emptied_daily', true);}
	if (answer.kitchen_area_appliances_countertop_etc_is_clean == "true"){g_form.setValue('kitchen_area_appliances_countertop_etc_is_clean', true);}
	if (answer.appliances_are_in_good_condition_and_are_csa_or_ulc_approved == "true"){g_form.setValue('appliances_are_in_good_condition_and_are_csa_or_ulc_approved', true);}
	if (answer.one_appliance_is_plugged_in_the_same_socket_at_the_same_time == "true"){g_form.setValue('one_appliance_is_plugged_in_the_same_socket_at_the_same_time', true);}
	if (answer.parking_lot_and_outside_of_the_building_are_in_good_condition_snow_removal_salting_lighting == "true"){g_form.setValue('parking_lot_and_outside_of_the_building_are_in_good_condition_snow_removal_salting_lighting', true);}
	if (answer.other == "true"){g_form.setValue('other', true);}


	//Load MVRSs
	g_form.setValue('hazard_s_to_report_in_aisles_and_flooring',JSON.stringify(answer.hazard_s_to_report_in_aisles_and_flooring));
	g_form.setValue('hazard_s_to_report_in_environment',JSON.stringify(answer.hazard_s_to_report_in_environment));
	g_form.setValue('hazard_s_to_report_in_electrical',JSON.stringify(answer.hazard_s_to_report_in_electrical));
	g_form.setValue('hazard_s_to_report_in_first_aid_and_emergency_preparedness',JSON.stringify(answer.hazard_s_to_report_in_first_aid_and_emergency_preparedness));
	g_form.setValue('hazard_s_to_housekeeping',JSON.stringify(answer.hazard_s_to_housekeeping));
	g_form.setValue('hazard_s_to_posting_requirements',JSON.stringify(answer.hazard_s_to_posting_requirements));
	g_form.setValue('hazard_s_to_storage_shelving_and_cabinets',JSON.stringify(answer.hazard_s_to_storage_shelving_and_cabinets));
	g_form.setValue('hazard_s_to_washrooms_and_kitchens',JSON.stringify(answer.hazard_s_to_washrooms_and_kitchens));
	g_form.setValue('hazard_s_to_outdoor',JSON.stringify(answer.hazard_s_to_outdoor));
	g_form.setValue('hazard_s_to_others',JSON.stringify(answer.hazard_s_to_others));

}

function getParameterValue(name) {  
    name = name.replace(/[\[]/, "\\\[").replace(/[\]]/, "\\\]");  
    var regexS = "[\\?&]" + name + "=([^&#]*)";  
    var regex = new RegExp(regexS);  
    var results = regex.exec(top.location);  
    if (results == null) {  
        return "";  
    } else {  
        return unescape(results[1]);  
    }  
}
